#ifndef QC_WATCHDOG_OWNER_H
#define QC_WATCHDOG_OWNER_H
#include <stdint.h>
#include <sys/types.h>
enum qw_state {QW_EMPTY,QW_UNKNOWN,QW_ENABLING,QW_ACTIVE5,QW_DISABLED,QW_HOLD};
enum qw_phase {QW_NEXT=1,QW_RETIRE=2};
#define QW_SESSION_NS UINT64_C(10000000000)
struct qw_owner {
 int fd;
 enum qw_state state;
 enum qw_phase phase;
 dev_t device,node_filesystem;
 ino_t node_inode;
 uint64_t last_ns,start_ns,session_start_ns,session_deadline_ns;
 unsigned capture_progress;
};
#define QW_OWNER_EMPTY { .fd=-1 }
/* Trusted exact driver/core/image and sole open-description custody, no aliases,
 * concurrent I/O/fd-table changes/reentry. Static fresh/disjoint objects only.
 * Preopen already STARTS hardware. Move metadata-only take leaves UNKNOWN, never
 * armed proof. No actor opens/duplicates/closes here. Source associations and
 * original provider/backing admission are NOT proved by descriptor metadata. */
int qw_owner_take(struct qw_owner *,int *,dev_t);
/* One-shot before unchanged memory initializer; actual clock must be >=start
 * and <start+2s. Latches start+10s for this owned lifetime, never renewed by begin.
 * Failure is sticky HOLD. No watchdog control/service; no setup restart API. */
int qw_owner_seal_session(struct qw_owner *,uint64_t);
/* Supplied deadline MUST equal the already sealed one on EVERY begin. */
int qw_owner_begin(struct qw_owner *,uint64_t,enum qw_phase,uint64_t);
int qw_owner_check(struct qw_owner *); /* active phase, real clock, <2s */
/* ONLY exact producer callsite after full raw CRC/extent/status and ACTIVE keyed
 * receipt/sequence checks. At most once per NEXT; not a generic feeder API. */
int qw_owner_capture_progress(struct qw_owner *);
/* Trusted integration calls ONLY after real successful producer/postchecks or
 * normal END/QUERY/ACK and cleanup. No caller-supplied 'qualified' Boolean.
 * DISABLED is ioctl ACK/logical state only, not electrical/DMA stop proof. */
int qw_owner_disable_boundary(struct qw_owner *);
int qw_owner_idle_observe(struct qw_owner *); /* DISABLED; no servicing */
int qw_owner_give_back(struct qw_owner *,int *); /* DISABLED custody move, no close */
void qw_owner_fail(struct qw_owner *); /* sticky HOLD, no IO, no armed guarantee */
/* No reset/close/destructor/HOLD-clear/retry/periodic thread or timer. On failure
 * actual FD stays owned, unless caller violates trusted custody. Failed disable
 * may already have stopped it; HOLD NEVER guarantees armed recovery. Final close
 * is outside this API; Linux close error cannot preserve an actual description
 * merely by retaining its former numeric FD or retrying it. Nominal5s unchanged. */
#endif

for mode, cc, ar, nm, readelf, flags in modes:
    command([cc, '--version'], mode + '-compiler-version')
    command([cc, '-dumpmachine'], mode + '-compiler-target')
    objects = []
    for unit in units:
        obj = out / 'objects' / (mode + '-' + unit + '.o')
        if unit not in report['compiled_units_per_platform']:
            if pin(out / 'source' / (unit + '.c')) != previous['source_files'][unit + '.c']:
                raise RuntimeError('reused unit source differs from v1')
            old = OLD_RUN / 'objects' / obj.name
            deps = shlex.split(old.with_suffix('.d').read_text().replace('\\\n', '').split(':', 1)[1])
            for name in deps:
                if pin(Path(name)) != previous['compiled_source_header_closure'][name]:
                    raise RuntimeError('reused object dependency drift: ' + name)
            for suffix in ('.o', '.d', '.su'):
                copy(old.with_suffix(suffix), obj.with_suffix(suffix))
            report['reused_objects'][str(old)] = pin(old)
            objects.append(obj)
            continue
        # Exact legacy compact-source policy from retained v6 builder;
        # no suppression on the new standalone owner implementation.
        legacy = ['-Wno-misleading-indentation'] if unit != 'watchdog_owner' else []
        command([cc, *flags, '-std=gnu11', '-Wall', '-Wextra', '-Werror', *legacy,
                 '-fno-common', '-ffunction-sections', '-fdata-sections', '-fstack-usage',
                 '-fstack-protector-strong', '-D_FORTIFY_SOURCE=2',
                 '-I' + str(out / 'source'), '-I' + str(out / 'source/framework/include'),
                 '-MD', '-MF', obj.with_suffix('.d'), '-c', out / 'source' / (unit + '.c'), '-o', obj],
                mode + '-cc-' + unit)
        objects.append(obj)
    archive = out / ('libqc07f-native-watchdog-owner-v2-' + mode + '.a')
    command([ar, 'rcsD', archive, *objects], mode + '-archive')
    reloc = out / (mode + '-native-watchdog-owner-v2-NOT-EXECUTABLE.o')
    command([cc, *flags, '-nostdlib', '-r', *objects, '-Wl,-Map=' + str(out / (mode + '.map')),
             '-o', reloc], mode + '-relocatable-link')
    command([readelf, '-h', '-A', '-r', '-W', reloc], mode + '-ELF-relocations')
    command([nm, '-u', reloc], mode + '-undefined-symbols')
    command([nm, '-g', '--defined-only', reloc], mode + '-defined-symbols')
    report.setdefault('tools', {})[mode] = {name: {'resolved': str(Path(path).resolve()), **pin(Path(path))}
        for name, path in (('cc', cc), ('ar', ar), ('nm', nm), ('readelf', readelf))}
    for p in (archive, reloc):
        report['artifacts'][p.name] = {**pin(p), 'executed': False}
closure = {}
for path in (out / 'objects').glob('*.d'):
    for name in shlex.split(path.read_text().replace('\\\n', '').split(':', 1)[1]):
        p = Path(name)
        if p.is_file():
            closure[str(p)] = pin(p)
report['compiled_source_header_closure'] = closure
for name in closure:
    p = Path(name)
    copy(p, out / 'inputs/consumed-header-closure' / p.relative_to('/'))

static int native_guard_present(void)
{return !stop&&!native.retirement_uncertain&&!source_clock.failed&&native.watchdog.fd>=3&&
 (native.watchdog.state==QW_UNKNOWN||native.watchdog.state==QW_DISABLED||native.watchdog.state==QW_ACTIVE5);}
static int prepare_output(struct qc_rtsp_context *c,uint64_t begin)
{
 int forecast=nh_memory_runtime_gate(&memory_state,NH_MEM_PRE_NEXT,begin);
 if(forecast){if(forecast==NH_MEM_CLOCK)native.retirement_uncertain=1;return CAMERA_NOT_READY;}
 if(qw_owner_check(&c->watchdog)){nh_native_fence(NULL);return CAMERA_IO_ERROR;}
 if(c->resident_storage)return CAMERA_OK;
 if(!memory_state.ledger.initialized)return CAMERA_NOT_READY;
 if(raw_reuse_requested){c->resident_storage=raw;return CAMERA_OK;} /* already-owned/paid raw pages, NEVER credit twice */
 c->resident_storage=malloc(1048576);if(!c->resident_storage)return CAMERA_NOT_READY;
 int reason=nh_memory_prefault_owned(&memory_state,2,c->resident_storage,1048576,begin);
 if(!reason)reason=nh_memory_runtime_gate(&memory_state,NH_MEM_PRE_NEXT,begin);
 if(reason){if(reason==NH_MEM_CLOCK)native.retirement_uncertain=1;return CAMERA_NOT_READY;}
 return CAMERA_OK;
}
static int before_encode_gate(uint64_t begin)
{
 int result=nh_memory_runtime_gate(&memory_state,NH_MEM_PRE_NEXT,begin);
 if(result==NH_MEM_CLOCK)native.retirement_uncertain=1;
 return result?CAMERA_NOT_READY:CAMERA_OK;

static void native_init_legacy(void)
{source_context_init(&native);memset(&source_clock,0,sizeof(source_clock));sensor_baseline_requested=0;memset(&sensor_baseline_report,0,sizeof(sensor_baseline_report));memset(&memory_state,0,sizeof(memory_state));codec_live_bytes=0;storage_selected=0;raw_reuse_requested=0;}
int nh_native_storage_select(const char *mode)
{
 if(!mode||storage_selected||memory_state.ledger.initialized||native.continuous_frame>=0||native.h264_stream_fd>=0)return CAMERA_NOT_READY;
 if(!strcmp(mode,"raw-reuse-k75"))raw_reuse_requested=1;
 else if(strcmp(mode,"separate"))return CAMERA_INVALID;
 storage_selected=1;return CAMERA_OK;
}
int nh_native_optin_exact139(void)
{
 if(native.retirement_uncertain||native.continuous_frame>=0||native.continuous_sensor>=0||native.h264_stream_fd>=0||sensor_baseline_requested)return CAMERA_NOT_READY;
 sensor_baseline_requested=1;return CAMERA_OK;
}
void nh_native_sensor_report(void){nh_sensor_log(&sensor_baseline_report);}
static int native_memory_start_legacy(uint64_t start)
{
 if(!native_guard_present())return CAMERA_NOT_READY;
 if(!storage_selected)return CAMERA_NOT_READY;
 int r=nh_memory_runtime_init(&memory_state,start,nh_native_now,nh_native_cancelled,NULL,raw_reuse_requested);
 if(!r)r=nh_memory_runtime_gate(&memory_state,NH_MEM_INITIAL,start);
 if(r==NH_MEM_CLOCK)native.retirement_uncertain=1;
 return r?CAMERA_NOT_READY:CAMERA_OK;

int nh_native_cancelled(void *unused)
{
 (void)unused;
 if(stop||native.retirement_uncertain)return 1;
 if(native.receipt_armed){
  struct qc_capture_receipt proof;
  if(qc_receipt_query(native.continuous_frame,&native.receipt_key,&proof)||
     proof.state!=QC_RECEIPT_ACTIVE||proof.reason||proof.stop_result||proof.stopped_ns){
   native.retirement_uncertain=1;return 1;
  }
  native.receipt_evidence=proof;
 }
 return 0;
}
static int native_next_legacy(void *unused,struct camera_packet *p,struct nh_key *key)
{
 (void)unused;
 if(stop)return CAMERA_DISCONNECTED;
 if(!sensor_baseline_requested)return CAMERA_NOT_READY; /* no silent table preparation */
 if(native.retirement_uncertain)return CAMERA_IO_ERROR;
 if(lifetime())return CAMERA_IO_ERROR; /* reject receipt-less/legacy codec ABI before capture */
 int r=produce_h264_frame(&native,0,p);if(r)return r;
 if(lifetime())return CAMERA_IO_ERROR;
 if(nh_native_cancelled(NULL))return CAMERA_IO_ERROR;
 if(native.produced_timing.encoded-native.produced_timing.begin>=2000){native.retirement_uncertain=1;return CAMERA_IO_ERROR;}
  *key=(struct nh_key){native.receipt_key.source_instance,native.receipt_key.file_instance,
                     native.receipt_key.generation,native.capture_sequence,native.produced_nal_crc32_bzip2};
 expected=*p;return CAMERA_OK;
}
static int native_release_legacy(void *unused,const struct camera_packet *p)
{
 (void)unused;
 if(native.retirement_uncertain||!native.produced_storage||p->data!=expected.data||
    p->bytes!=expected.bytes||p->monotonic_ns!=expected.monotonic_ns)return CAMERA_IO_ERROR;
 release_h264_frame(&native,p);memset(&expected,0,sizeof(expected));return CAMERA_OK;
}
static int native_retire_body(void *unused)
{
 (void)unused;int r=idle_h264_checked(&native);
 fprintf(stderr,"NH_NATIVE_RETIRE result=%d source=%llu file=%llu generation=%llu state=%u reason=%u stop_result=%d stopped_ns=%llu armed=%u uncertain=%d\n",
